import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Codex IDE Extension","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-ide.md","filePath":"products/ai-coding/codex/codex-ide.md","lastUpdated":1787110548000}'),n={name:"products/ai-coding/codex/codex-ide.md"};function s(d,e,i,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="codex-ide-extension" tabindex="-1">Codex IDE Extension <a class="header-anchor" href="#codex-ide-extension" aria-label="Permalink to &quot;Codex IDE Extension&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — install the extension, attach the file you already have open, and review the edit beside the source. The IDE is one Codex surface. It shares <code>AGENTS.md</code>, sandbox, and approval with the CLI.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/ide</a>. Docs: <a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE extension</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Account</td><td>A ChatGPT plan that includes Codex</td></tr><tr><td>Editor</td><td>VS Code, Cursor, Windsurf, VS Code Insiders, Xcode, or a JetBrains IDE</td></tr><tr><td>Repo</td><td>A project folder you already know</td></tr></tbody></table><p><strong>Learning objectives</strong>: install or enable Codex in your editor; start a chat that already has the open file; review a focused diff in place; hand a long task to Cloud without leaving the editor.</p><p><strong>Non-goals</strong>: CLI install (<a href="./codex-cli.html">CLI</a>); Cloud environment setup (<a href="./codex-cloud.html">Cloud</a>); desktop Chat / Work / Codex switcher (<a href="./codex-ai.html">product line</a>, <a href="./chatgpt-work.html">Work</a>).</p><h2 id="what-the-ide-extension-is-—-and-is-not" tabindex="-1">What the IDE extension is — and is not <a class="header-anchor" href="#what-the-ide-extension-is-—-and-is-not" aria-label="Permalink to &quot;What the IDE extension is — and is not&quot;">​</a></h2><p>The extension puts Codex <strong>beside the code</strong>. Open files, the current selection, and recent chats go into the composer. You read a short summary and a focused diff next to the source.</p><p>It is <strong>not</strong>:</p><ul><li>A second agent with a different config. Same <code>~/.codex/config.toml</code>, same <code>AGENTS.md</code>.</li><li>The desktop Codex surface. Desktop Codex lives in the <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a>: visual diffs, PR sidebar, multi-repo, Computer Use. Mapped on the <a href="./codex-ai.html">product line</a> — no duplicate desktop tutorial here.</li><li>A replacement for <code>codex exec</code> in CI.</li></ul><p>Choose the IDE when the task is anchored to the file or selection you are looking at. Choose the CLI when the job is scriptable. Choose <a href="./codex-cloud.html">Cloud</a> when it should keep running after you close the laptop.</p><h2 id="step-1-—-install-or-enable-codex" tabindex="-1">Step 1 — Install or enable Codex <a class="header-anchor" href="#step-1-—-install-or-enable-codex" aria-label="Permalink to &quot;Step 1 — Install or enable Codex&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>How</th></tr></thead><tbody><tr><td>Visual Studio Code</td><td><a href="https://marketplace.visualstudio.com/items?itemName=openai.chatgpt" target="_blank" rel="noreferrer">openai.chatgpt</a> or <code>vscode:extension/openai.chatgpt</code></td></tr><tr><td>Cursor</td><td><code>cursor:extension/openai.chatgpt</code></td></tr><tr><td>Windsurf</td><td><code>windsurf:extension/openai.chatgpt</code></td></tr><tr><td>VS Code Insiders</td><td>Same Marketplace item</td></tr><tr><td>Xcode</td><td><a href="https://developer.apple.com/documentation/Xcode/setting-up-coding-intelligence" target="_blank" rel="noreferrer">Setting up coding intelligence</a>; pick Codex as the agent</td></tr><tr><td>JetBrains IDEs</td><td><a href="https://www.jetbrains.com/help/ai-assistant/codex-agent.html" target="_blank" rel="noreferrer">Codex agent in AI Assistant</a>; open AI Chat and select Codex</td></tr></tbody></table><p>Sign in with the same ChatGPT account you use for the CLI.</p><h2 id="step-2-—-open-codex" tabindex="-1">Step 2 — Open Codex <a class="header-anchor" href="#step-2-—-open-codex" aria-label="Permalink to &quot;Step 2 — Open Codex&quot;">​</a></h2><p><strong>VS Code, Cursor, or Windsurf:</strong> click the Codex icon. If it is missing, run <strong>Codex: Open Codex Sidebar</strong> from the Command Palette.</p><p><strong>Xcode:</strong> open the coding assistant, start a chat, choose Codex.</p><p><strong>JetBrains:</strong> open AI Chat, select Codex.</p><h2 id="step-3-—-first-chat-with-editor-context" tabindex="-1">Step 3 — First chat, with editor context <a class="header-anchor" href="#step-3-—-first-chat-with-editor-context" aria-label="Permalink to &quot;Step 3 — First chat, with editor context&quot;">​</a></h2><p>Open a project you already know. Ask for an explanation or a small edit. Create Git checkpoints before and after so you can revert.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@src/auth/session.ts Explain how session refresh works, then add a test for</span></span>
<span class="line"><span>the expired-token path only. Do not change the cookie format.</span></span></code></pre></div><p>Attach the open file or the selection from the composer instead of restating the problem. Official prompting: <a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Use editor context</a>.</p><h2 id="step-4-—-review-beside-the-source" tabindex="-1">Step 4 — Review beside the source <a class="header-anchor" href="#step-4-—-review-beside-the-source" aria-label="Permalink to &quot;Step 4 — Review beside the source&quot;">​</a></h2><p>Read the summary. Inspect the changed lines. Keep only the edits you want. Ask for a follow-up in the same chat. Do not accept a multi-file rewrite you have not opened.</p><h2 id="step-5-—-delegate-when-the-task-grows" tabindex="-1">Step 5 — Delegate when the task grows <a class="header-anchor" href="#step-5-—-delegate-when-the-task-grows" aria-label="Permalink to &quot;Step 5 — Delegate when the task grows&quot;">​</a></h2><p>Keep quick iterations local. When the job needs more time, connect Codex web and send it to <a href="./codex-cloud.html">Cloud</a>. The chat stays in the editor so you can review the result later.</p><p>Official: <a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">Delegate from the IDE extension</a>.</p><h2 id="use-the-ide-when" tabindex="-1">Use the IDE when… <a class="header-anchor" href="#use-the-ide-when" aria-label="Permalink to &quot;Use the IDE when…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Why</th></tr></thead><tbody><tr><td>Focused edits</td><td>Relevant files and Codex stay in one view</td></tr><tr><td>Unfamiliar code</td><td>Ask about the symbols already open</td></tr><tr><td>Review in place</td><td>Diff sits next to the source</td></tr><tr><td>A larger task</td><td>Start Cloud from the IDE, return to the result</td></tr></tbody></table><p>Commands and settings: <a href="https://learn.chatgpt.com/docs/developer-commands?surface=ide" target="_blank" rel="noreferrer">IDE commands</a>, <a href="https://learn.chatgpt.com/docs/developer-settings?surface=ide" target="_blank" rel="noreferrer">IDE settings</a>. Docs pages use <code>?surface=ide</code> — if a page looks like the CLI, check the surface selector.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Describing a file instead of attaching it</td><td>Codex guesses the wrong module</td><td>Mention the open file or selection</td></tr><tr><td>Treating the IDE as a different agent</td><td>Config / <code>AGENTS.md</code> “not loading”</td><td>Same config model as the CLI; trust the project</td></tr><tr><td>Leaving a long job on the laptop</td><td>The editor session dies with sleep</td><td>Delegate to <a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>Looking for the PR sidebar here</td><td>That is desktop Codex</td><td><a href="./codex-ai.html">Product line</a> · <a href="./chatgpt-work.html#work-vs-codex-on-desktop">Work vs Codex</a></td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>You have <code>Button.tsx</code> open and a failing visual test. Attach the file, ask for the smallest CSS fix, review the diff beside the component. If the fix turns into a token-migration across the design system, hand that off to Cloud and keep the IDE chat for review.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Prompting with editor context → <a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Prompting</a></li><li>Best practices → <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">guides/best-practices</a></li><li>Long jobs → <a href="./codex-cloud.html">Cloud</a></li><li>Flags and slash commands → <a href="./codex-cheatsheet.html">Cheatsheet</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">IDE extension (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE extension (docs)</a></li><li><a href="https://learn.chatgpt.com/docs/developer-commands?surface=ide" target="_blank" rel="noreferrer">IDE commands</a></li><li><a href="https://learn.chatgpt.com/docs/developer-settings?surface=ide" target="_blank" rel="noreferrer">IDE settings</a></li><li><a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Prompting · editor context</a></li><li><a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">Delegate from the IDE</a></li><li><a href="https://marketplace.visualstudio.com/items?itemName=openai.chatgpt" target="_blank" rel="noreferrer">VS Marketplace: openai.chatgpt</a></li></ul>`,38)])])}const x=t(n,[["render",s]]);export{m as __pageData,x as default};
